// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 duration, uint256 warpTo, uint256 expiration) public {
        duration = bound(duration, 1, 365 days);
        warpTo = bound(warpTo, 1, type(uint128).max);
        vm.assume(expiration > warpTo);

        // ERC-1271 signer acts as order maker (so the signature check passes)
        ERC1271Signer maker = new ERC1271Signer();
        // permissive base asset token (has code, transferFrom succeeds)
        FakeToken token = new FakeToken();

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: false,
            isLong: false,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        vm.warp(warpTo);

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = new bytes(0);

        uint256 positionId = c.fillOrder(order, sig, floorAssetTokenIds);

        // Rule: after filling ANY short order, the caller's position (the opposite-order id)
        // is recorded with expiration block.timestamp + duration (> 0).
        assertTrue(
            c.positionExpirations(positionId) == warpTo + duration,
            "filled order must record position expiration"
        );
    }
}

contract ERC1271Signer {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
